'use client';
import React,{useState,useEffect,useRef} from 'react';
import {LayoutDashboard,BookOpen,Plus,CalendarDays,ChartNoAxesCombined,Images,Layers,Settings as SettingsIcon,Upload,Download,ChevronLeft,ChevronRight,Search,ArrowUpRight,ArrowDownRight,ShieldCheck,Check,Image as ImageIcon,Trash2,Pencil,Menu,TrendingUp,Target,Activity,Flame,Wallet, X} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarContent,SidebarHeader,SidebarFooter,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarTrigger} from '@/components/ui/sidebar';
